  `objtainaccountcontroldays` varchar(10) DEFAULT NULL COMMENT '客户被自动回收后天内不允许被当前销售负责人再次领取（为0或空表示不控制） ',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
