  `releasetype` varchar(20) DEFAULT NULL,
  `active` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_account_public_pool__id` (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8;
