--
-- Table structure for table `ld_approvestep`
--

DROP TABLE IF EXISTS `ld_approvestep`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_approvestep` (
  `id` int(19) NOT NULL,
  `approveid` int(19) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `description` text,
  `ended` int(1) DEFAULT NULL,
  `step` int(1) DEFAULT NULL,
  `sequence` decimal(20,5) DEFAULT NULL,
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `approvetype` int(1) DEFAULT NULL,
  `approvevalue` varchar(255) DEFAULT NULL,
  `specifyapproverid` int(18) DEFAULT NULL,
  `alloweditbill` varchar(50) DEFAULT NULL,
  `countersigner` varchar(20) DEFAULT 'no',
  `augmentsinger` varchar(10) DEFAULT NULL,
  `module_field` text,
  `concurrentid` int(11) DEFAULT '0',
  `approveremarkrequire` varchar(20) DEFAULT 'no',
  `emptyapproverdeal` text,
  `steptype` varchar(20) DEFAULT 'approve',
  `isnewstep` varchar(20) DEFAULT 'no',
  `childids` varchar(255) DEFAULT NULL,
  `branchflowstepid` int(11) DEFAULT '0',
  `flowstepid` int(11) DEFAULT '0',
  `writesignrequired` varchar(10) DEFAULT 'no',
  `writesignlogtype` varchar(20) DEFAULT NULL,
  `approverremovetype` varchar(50) DEFAULT 'no',
  `approvalauthority` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

