DROP TABLE IF EXISTS `ld_budgetchange`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_budgetchange` (
  `budgetchangeid` int(19) NOT NULL AUTO_INCREMENT,
  `budgetchange_no` varchar(100) DEFAULT NULL,
  `change_date` date DEFAULT NULL,
  `change_type` varchar(255) DEFAULT NULL,
  `smownerid` int(11) DEFAULT NULL,
  `accountid` int(11) DEFAULT NULL,
  `customform14id` int(11) DEFAULT NULL,
  `deleted` int(19) NOT NULL DEFAULT '0',
  `approveby` int(11) DEFAULT NULL,
  `approvestatus` varchar(50) DEFAULT '未提交',
  `currentapprover` text,
  `createdtime` datetime DEFAULT NULL,
  `smcreatorid` int(19) DEFAULT NULL,
  `modifiedby` int(19) DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `form14_type` varchar(50) DEFAULT NULL,
  `approvetime` datetime DEFAULT NULL,
  `print_times` int(11) DEFAULT '0',
  `total` decimal(25,8) DEFAULT NULL,
  `subtotal` decimal(25,8) DEFAULT NULL,
  `adjustment` decimal(25,8) DEFAULT NULL,
  `discount_amount` decimal(25,8) DEFAULT NULL,
  `discount_percent` decimal(25,2) DEFAULT NULL,
  `discount_type` int(2) DEFAULT '0',
  `currency_id` int(19) DEFAULT '1',
  `currency_symbol` varchar(30) DEFAULT '¥',
  `conversion_rate` decimal(25,6) DEFAULT '1.000000',
  `pricebooksid` int(19) DEFAULT NULL,
  `advance_stage` varchar(100) DEFAULT NULL,
  `approvesubmitter` int(19) DEFAULT '0',
  `approvesubmittedtime` datetime DEFAULT NULL,
  `approveurgent` varchar(10) DEFAULT 'no',
  `approveexpediting` varchar(10) DEFAULT 'no',
  `currentapprovestepid` int(19) DEFAULT '0',
  `team_memberid` text,
  `kis_id` varchar(200) DEFAULT NULL,
  `kis_no` varchar(200) DEFAULT NULL,
  `exchtime` datetime DEFAULT NULL,
  `exchmsg` text,
  `latestpushtime` datetime DEFAULT NULL,
