,'yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(12,'客户联系次数Top10-柱状','客户联系次数Top10','chart',1,11,'ContactRecords','2021-09-03 11:36:35',NULL,0,NULL,10,'','desc',1,'',0,'0','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(13,'客户联系次数Top50-柱状','客户联系次数Top50','chart',1,12,'ContactRecords','2021-09-03 11:37:53',NULL,0,NULL,50,'','desc',1,'',0,'0','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(14,'客户服务次数统计表-柱状','','chart',1,13,'HelpDesk','2021-09-03 11:38:52',NULL,0,NULL,0,'','desc',1,'',0,'0','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(15,'服务人员服务次数统计表-柱状','服务人员服务次数统计表','chart',1,14,'HelpDesk','2021-09-03 11:40:18',NULL,0,NULL,0,'','desc',1,'',0,'0','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(16,'客户服务单故障类别统计表-柱状','客户服务单故障类别统计表','chart',1,15,'HelpDesk','2021-09-03 11:41:08',NULL,0,NULL,0,'','desc',1,'',0,'0','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(17,'客户公司性质分布统计-饼图','客户公司性质分布统计','chart',1,16,'Accounts','2021-09-03 11:42:09',NULL,0,NULL,0,'','desc',1,'',0,'0','no','yes','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(18,'客户省份分布统计-饼图','','chart',1,17,'Accounts','2021-09-03 11:42:49',NULL,0,NULL,0,'','desc',1,'',0,'0','no','yes','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(19,'客户销售负责人分布统计-饼图','客户销售负责人分布统计','chart',1,18,'Accounts','2021-09-03 11:43:26',NULL,0,NULL,0,'','desc',1,'',0,'0','no','yes','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(20,'销售漏斗-漏斗图','销售漏斗','chart',1,19,'Potentials','2021-09-03 11:45:03',NULL,0,NULL,0,'','desc',1,'',0,'0','no','yes','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(21,'客户收款金额Top10-柱状','客户收款金额Top10','chart',1,20,'CashBill','2021-09-03 11:47:12',NULL,0,NULL,10,'','desc',1,'',0,'0','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(22,'客户收款金额Top50-柱状','客户收款金额Top10','chart',1,21,'CashBill','2021-09-03 11:47:57',NULL,0,NULL,50,'','desc',1,'',0,'0','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(23,'客户签约金额堆叠图','客户签约金额堆叠图','chart',1,22,'Accounts','2021-09-03 11:53:24',NULL,0,NULL,0,'','desc',1,'',0,'0','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(24,'商机统计图_按销售负责人和销售阶段统计-多柱','商机统计图_按所属行业和销售阶段统计-多柱','chart',1,23,'Potentials','2021-09-03 11:58:29',NULL,0,NULL,0,'','desc',1,'',0,'0','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(25,'员工待转化线索','统计每个员工名下未转化成客户的线索数量','chart',1,24,'Leads','2022-07-21 15:41:34',NULL,0,NULL,0,'','desc',1,'',0,'no','no','no','','yes','Bottom',58,NULL,NULL,NULL,NULL,NULL),(26,'本季度预计成交重点商机TOP10','根据预计成交日期，按照非成交或失败状态的商机按预计合同金额大小排名','chart',NULL,25,'Potentials','2022-07-26 14:17:42',NULL,0,NULL,10,'','desc',1,'',0,'yes','no','yes','Potentials','yes','Bottom',58,NULL,NULL,'[null,{\"groupid\":\"1\",\"columnname\":\"\",\"comparator\":\"thisfq\",\"value\":\"2022-07-01\",\"columncondition\":\"and\"},{\"groupid\":\"1\",\"columnname\":\"\",\"comparator\":\"k\",\"value\":\"失败\",\"columncondition\":\"and\"},{\"groupid\":\"1\",\"columnname\":\"\",\"comparator\":\"k\",\"value\":\"成功\",\"columncondition\":\"\"}]','[null,{\"groupcondition\":\"\"}],{\"groupcondition\":\"\"}],{\"groupcondition\":\"\"}]',NULL),(27,'multiple_bar','','sqlchart',NULL,0,NULL,'2023-05-24 16:25:10',NULL,1,NULL,NULL,NULL,NULL,1,NULL,0,'no','no','no',NULL,'yes','Bottom',1,NULL,NULL,NULL,NULL,NULL),(28,'销售人员','','chart',NULL,NULL,'Leads','2023-05-24 16:58:38',NULL,1,NULL,0,'','desc',1,'',0,'no','no','no','','yes','Bottom',1,NULL,NULL,NULL,NULL,NULL),(307,'产品签约数量同比','','sqlchart',NULL,0,NULL,'2023-11-22 16:31:40','2023-11-28 19:17:21',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',73,'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	sum(p_num.pre_num) AS pre_num,\n	sum(p_num.now_num) AS now_num\nFROM\n	(\n		(\n			SELECT\n				timetype_table.where_time AS where_time,\n				timetype_table.group_time AS group_time,\n				pre_salesorder.salesorderid AS pre_id,\n				pre_salesorder.quantity AS pre_num,\n				now_salesorder.salesorderid AS now_id,\n				now_salesorder.quantity AS now_num\n			FROM\n				(\n					SELECT\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (NOW())\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (NOW())\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (NOW())\n							ELSE\n								YEAR (NOW())\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (date)\n							ELSE\n								MONTH (date)\n							END\n						) AS group_time\n					FROM\n						tmp_date a\n					WHERE\n						date LIKE \'%2023%\'\n					GROUP BY\n						group_time\n				) timetype_table\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						ELSE\n							YEAR (ld_salesorder.signed_data)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(now_s_detail.quantity) AS quantity\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail now_s_detail ON now_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				AND (\n					ld_salesorder.signed_data BETWEEN \'{starttime}\'\n					AND \'{endtime}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n			AND now_salesorder.group_time = timetype_table.group_time\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 QUARTER\n								)\n							)\n						ELSE\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(pre_s_detail.quantity) AS quantity\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail pre_s_detail ON pre_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n			AND pre_salesorder.group_time = timetype_table.group_time\n			GROUP BY\n				timetype_table.group_time\n		)\n		UNION ALL\n			(\n				SELECT\n					timetype_table.where_time AS where_time,\n					timetype_table.group_time AS group_time,\n					pre_servicecontracts.servicecontractsid AS pre_id,\n					pre_servicecontracts.quantity AS pre_num,\n					now_servicecontracts.servicecontractsid AS now_id,\n					now_servicecontracts.quantity AS now_num\n				FROM\n					(\n						SELECT\n							(\n								CASE\n								WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n									YEAR (NOW())\n								WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n									YEAR (NOW())\n								WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n									QUARTER (NOW())\n								ELSE\n									YEAR (NOW())\n								END\n							) AS where_time,\n							(\n								CASE\n								WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n									MONTH (date)\n								WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n									QUARTER (date)\n								WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n									MONTH (date)\n								ELSE\n									MONTH (date)\n								END\n							) AS group_time\n						FROM\n							tmp_date a\n						WHERE\n							date LIKE \'%2023%\'\n						GROUP BY\n							group_time\n					) timetype_table\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (due_date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (due_date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (due_date)\n							ELSE\n								YEAR (due_date)\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (due_date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (due_date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (due_date)\n							ELSE\n								MONTH (due_date)\n							END\n						) AS group_time,\n						sum(now_sv_detail.quantity) AS quantity\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail now_sv_detail ON now_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = now_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n							ld_products.productcategory,\n							\'{productcategory}\'\n						)\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.approvestatus,\n						\'{approvestatus}\'\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.smownerid,\n						\'{userscope}\'\n					)\n					AND (\n						ld_servicecontracts.due_date BETWEEN \'{starttime}\'\n						AND \'{endtime}\'\n					)\n					GROUP BY\n						where_time,\n						group_time\n				) now_servicecontracts ON now_servicecontracts.where_time = timetype_table.where_time\n				AND now_servicecontracts.group_time = timetype_table.group_time\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 QUARTER\n									)\n								)\n							ELSE\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (\n									ld_servicecontracts.due_date\n								)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							ELSE\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							END\n						) AS group_time,\n						sum(pre_sv_detail.quantity) AS quantity\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail pre_sv_detail ON pre_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = pre_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n							ld_products.productcategory,\n							\'{productcategory}\'\n						)\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.approvestatus,\n						\'{approvestatus}\'\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.smownerid,\n						\'{userscope}\'\n					)\n					GROUP BY\n						where_time,\n						group_time\n				) pre_servicecontracts ON pre_servicecontracts.where_time = timetype_table.where_time\n				AND pre_servicecontracts.group_time = timetype_table.group_time\n				GROUP BY\n					timetype_table.group_time\n			)\n	) p_num\nGROUP BY\n	p_num.group_time','Default',NULL,NULL,'product_contracted_quantity_y_to_y'),(309,'产品签约金额同比','','sqlchart',NULL,0,NULL,'2023-11-23 16:07:10','2023-11-28 16:24:14',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',73,'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	sum(p_num.pre_tax_amount) AS pre_tax_amount,\n	sum(p_num.now_tax_amount) AS now_tax_amount\nFROM\n	(\n		(\n			SELECT\n				timetype_table.where_time AS where_time,\n				timetype_table.group_time AS group_time,\n				pre_salesorder.salesorderid AS pre_id,\n				pre_salesorder.tax_amount AS pre_tax_amount,\n				now_salesorder.salesorderid AS now_id,\n				now_salesorder.tax_amount AS now_tax_amount\n			FROM\n				(\n					SELECT\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (NOW())\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (NOW())\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (NOW())\n							ELSE\n								YEAR (NOW())\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (date)\n							ELSE\n								MONTH (date)\n							END\n						) AS group_time\n					FROM\n						tmp_date a\n					WHERE\n						date LIKE \'%2023%\'\n					GROUP BY\n						group_time\n				) timetype_table\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						ELSE\n							YEAR (ld_salesorder.signed_data)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(\n						now_s_detail.tax_amount / ld_salesorder.conversion_rate\n					) AS tax_amount\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail now_s_detail ON now_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				AND (\n					ld_salesorder.signed_data BETWEEN \'{starttime}\'\n					AND \'{endtime}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n			AND now_salesorder.group_time = timetype_table.group_time\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 QUARTER\n								)\n							)\n						ELSE\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 YEAR\n								)\n							)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (signed_data)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(\n						pre_s_detail.tax_amount / ld_salesorder.conversion_rate\n					) AS tax_amount\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail pre_s_detail ON pre_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n			AND pre_salesorder.group_time = timetype_table.group_time\n			GROUP BY\n				timetype_table.group_time\n		)\n		UNION ALL\n			(\n				SELECT\n					timetype_table.where_time AS where_time,\n					timetype_table.group_time AS group_time,\n					pre_servicecontracts.servicecontractsid AS pre_id,\n					pre_servicecontracts.tax_amount AS pre_tax_amount,\n					now_servicecontracts.servicecontractsid AS now_id,\n					now_servicecontracts.tax_amount AS now_tax_amount\n				FROM\n					(\n						SELECT\n							(\n								CASE\n								WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n									YEAR (NOW())\n								WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n									YEAR (NOW())\n								WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n									QUARTER (NOW())\n								ELSE\n									YEAR (NOW())\n								END\n							) AS where_time,\n							(\n								CASE\n								WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n									MONTH (date)\n								WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n									QUARTER (date)\n								WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n									MONTH (date)\n								ELSE\n									MONTH (date)\n								END\n							) AS group_time\n						FROM\n							tmp_date a\n						WHERE\n							date LIKE \'%2023%\'\n						GROUP BY\n							group_time\n					) timetype_table\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (due_date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (due_date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (due_date)\n							ELSE\n								YEAR (due_date)\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (due_date)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (due_date)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (due_date)\n							ELSE\n								MONTH (due_date)\n							END\n						) AS group_time,\n						sum(\n							now_sv_detail.tax_amount / ld_servicecontracts.conversion_rate\n						) AS tax_amount\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail now_sv_detail ON now_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = now_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n							ld_products.productcategory,\n							\'{productcategory}\'\n						)\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.approvestatus,\n						\'{approvestatus}\'\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.smownerid,\n						\'{userscope}\'\n					)\n					AND (\n						ld_servicecontracts.due_date BETWEEN \'{starttime}\'\n						AND \'{endtime}\'\n					)\n					GROUP BY\n						where_time,\n						group_time\n				) now_servicecontracts ON now_servicecontracts.where_time = timetype_table.where_time\n				AND now_servicecontracts.group_time = timetype_table.group_time\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								QUARTER (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 QUARTER\n									)\n								)\n							ELSE\n								YEAR (\n									DATE_ADD(\n										ld_servicecontracts.due_date,\n										INTERVAL 1 YEAR\n									)\n								)\n							END\n						) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n								QUARTER (\n									ld_servicecontracts.due_date\n								)\n							WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							ELSE\n								MONTH (\n									ld_servicecontracts.due_date\n								)\n							END\n						) AS group_time,\n						sum(\n							pre_sv_detail.tax_amount / ld_servicecontracts.conversion_rate\n						) AS tax_amount\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail pre_sv_detail ON pre_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = pre_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n							ld_products.productcategory,\n							\'{productcategory}\'\n						)\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.approvestatus,\n						\'{approvestatus}\'\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.smownerid,\n						\'{userscope}\'\n					)\n					GROUP BY\n						where_time,\n						group_time\n				) pre_servicecontracts ON pre_servicecontracts.where_time = timetype_table.where_time\n				AND pre_servicecontracts.group_time = timetype_table.group_time\n				GROUP BY\n					timetype_table.group_time\n			)\n	) p_num\nGROUP BY\n	p_num.group_time','Default',NULL,NULL,'product_contracted_amount_y_to_y'),(310,'产品订单数量同比','','sqlchart',NULL,0,NULL,'2023-11-23 16:16:37','2023-11-23 20:18:58',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',73,'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	p_num.pre_num,\n	p_num.now_num\nFROM\n	(\n		SELECT\n			timetype_table.where_time AS where_time,\n			timetype_table.group_time AS group_time,\n			pre_salesorder.quantity AS pre_num,\n			now_salesorder.quantity AS now_num\n		FROM\n			(\n				SELECT\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (NOW())\n						ELSE\n							YEAR (NOW())\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (date)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (date)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (date)\n						ELSE\n							MONTH (date)\n						END\n					) AS group_time\n				FROM\n					tmp_date a\n				WHERE\n					date LIKE \'%2023%\'\n				GROUP BY\n					group_time\n			) timetype_table\n		LEFT JOIN (\n			SELECT\n				now_s_detail.id AS salesorderid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (ld_salesorder.signed_data)\n					ELSE\n						YEAR (ld_salesorder.signed_data)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					ELSE\n						MONTH (ld_salesorder.signed_data)\n					END\n				) AS group_time,\n				sum(now_s_detail.tax_amount) AS tax_amount,\n				sum(now_s_detail.quantity) AS quantity\n			FROM\n				ld_salesorder\n			LEFT JOIN ld_salesorderdetail now_s_detail ON now_s_detail.id = ld_salesorder.salesorderid\n			LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.smownerid,\n				\'{userscope}\'\n			)\n			AND (\n				ld_salesorder.signed_data BETWEEN \'{starttime}\'\n				AND \'{endtime}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n		AND now_salesorder.group_time = timetype_table.group_time\n		LEFT JOIN (\n			SELECT\n				pre_s_detail.id AS salesorderid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (signed_data)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					ELSE\n						MONTH (ld_salesorder.signed_data)\n					END\n				) AS group_time,\n				sum(pre_s_detail.tax_amount) AS tax_amount,\n				sum(pre_s_detail.quantity) AS quantity\n			FROM\n				ld_salesorder\n			LEFT JOIN ld_salesorderdetail pre_s_detail ON pre_s_detail.id = ld_salesorder.salesorderid\n			LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.smownerid,\n				\'{userscope}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n		AND pre_salesorder.group_time = timetype_table.group_time\n		GROUP BY\n			timetype_table.group_time\n	) p_num\nGROUP BY\n	p_num.group_time','Default',NULL,NULL,'product_salesorders_quantity_y_to_y'),(311,'产品订单金额同比','','sqlchart',NULL,0,NULL,'2023-11-23 16:38:35','2023-11-23 20:20:40',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',73,'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	p_num.pre_tax_amount,\n	p_num.now_tax_amount\nFROM\n	(\n		SELECT\n			timetype_table.where_time AS where_time,\n			timetype_table.group_time AS group_time,\n			pre_salesorder.tax_amount AS pre_tax_amount,\n			now_salesorder.tax_amount AS now_tax_amount\n		FROM\n			(\n				SELECT\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (NOW())\n						ELSE\n							YEAR (NOW())\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (date)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (date)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (date)\n						ELSE\n							MONTH (date)\n						END\n					) AS group_time\n				FROM\n					tmp_date a\n				WHERE\n					date LIKE \'%2023%\'\n				GROUP BY\n					group_time\n			) timetype_table\n		LEFT JOIN (\n			SELECT\n				now_s_detail.id AS salesorderid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (ld_salesorder.signed_data)\n					ELSE\n						YEAR (ld_salesorder.signed_data)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					ELSE\n						MONTH (ld_salesorder.signed_data)\n					END\n				) AS group_time,\n				sum(\n					now_s_detail.tax_amount / ld_salesorder.conversion_rate\n				) AS tax_amount\n			FROM\n				ld_salesorder\n			LEFT JOIN ld_salesorderdetail now_s_detail ON now_s_detail.id = ld_salesorder.salesorderid\n			LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.smownerid,\n				\'{userscope}\'\n			)\n			AND (\n				ld_salesorder.signed_data BETWEEN \'{starttime}\'\n				AND \'{endtime}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n		AND now_salesorder.group_time = timetype_table.group_time\n		LEFT JOIN (\n			SELECT\n				pre_s_detail.id AS salesorderid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						YEAR (\n							DATE_ADD(\n								ld_salesorder.signed_data,\n								INTERVAL 1 YEAR\n							)\n						)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (signed_data)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_salesorder.signed_data)\n					ELSE\n						MONTH (ld_salesorder.signed_data)\n					END\n				) AS group_time,\n				sum(\n					pre_s_detail.tax_amount / ld_salesorder.conversion_rate\n				) AS tax_amount\n			FROM\n				ld_salesorder\n			LEFT JOIN ld_salesorderdetail pre_s_detail ON pre_s_detail.id = ld_salesorder.salesorderid\n			LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_salesorder.smownerid,\n				\'{userscope}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n		AND pre_salesorder.group_time = timetype_table.group_time\n		GROUP BY\n			timetype_table.group_time\n	) p_num\nGROUP BY\n	p_num.group_time','Default',NULL,NULL,'product_salesorders_amount_y_to_y'),(312,'产品开票金额同比','','sqlchart',NULL,0,NULL,'2023-11-23 16:58:47','2023-11-23 20:28:06',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',73,'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	p_num.pre_tax_amount,\n	p_num.now_tax_amount\nFROM\n	(\n		SELECT\n			timetype_table.where_time AS where_time,\n			timetype_table.group_time AS group_time,\n			pre_salesorder.tax_amount AS pre_tax_amount,\n			now_salesorder.tax_amount AS now_tax_amount\n		FROM\n			(\n				SELECT\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (NOW())\n						ELSE\n							YEAR (NOW())\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (date)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (date)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (date)\n						ELSE\n							MONTH (date)\n						END\n					) AS group_time\n				FROM\n					tmp_date a\n				WHERE\n					date LIKE \'%2023%\'\n				GROUP BY\n					group_time\n			) timetype_table\n		LEFT JOIN (\n			SELECT\n				now_s_detail.id AS invoiceid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (ld_invoice.invoicedate)\n					ELSE\n						YEAR (ld_invoice.invoicedate)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_invoice.invoicedate)\n					ELSE\n						MONTH (ld_invoice.invoicedate)\n					END\n				) AS group_time,\n				sum(\n					now_s_detail.tax_amount / ld_invoice.conversion_rate\n				) AS tax_amount\n			FROM\n				ld_invoice\n			LEFT JOIN ld_invoicedetail now_s_detail ON now_s_detail.id = ld_invoice.invoiceid\n			LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_invoice.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_invoice.smownerid,\n				\'{userscope}\'\n			)\n			AND (\n				ld_invoice.invoicedate BETWEEN \'{starttime}\'\n				AND \'{endtime}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n		AND now_salesorder.group_time = timetype_table.group_time\n		LEFT JOIN (\n			SELECT\n				pre_s_detail.id AS invoiceid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						YEAR (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 YEAR\n							)\n						)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_invoice.invoicedate)\n					ELSE\n						MONTH (ld_invoice.invoicedate)\n					END\n				) AS group_time,\n				sum(\n					pre_s_detail.tax_amount / ld_invoice.conversion_rate\n				) AS tax_amount\n			FROM\n				ld_invoice\n			LEFT JOIN ld_invoicedetail pre_s_detail ON pre_s_detail.id = ld_invoice.invoiceid\n			LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_invoice.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_invoice.smownerid,\n				\'{userscope}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n		AND pre_salesorder.group_time = timetype_table.group_time\n		GROUP BY\n			timetype_table.group_time\n	) p_num\nGROUP BY\n	p_num.group_time','Default',NULL,NULL,'product_invoice_amount_y_to_y'),(313,'产品出库数量同比','','sqlchart',NULL,0,NULL,'2023-11-23 17:29:23','2023-11-23 20:22:42',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',73,'SELECT\n	p_num.where_time,\n	p_num.group_time,\n	(\n		CASE\n		WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n			CONCAT(\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			CONCAT(p_num.group_time, \'月\')\n		END\n	) AS dispaly_group_time,\n	p_num.pre_num,\n	p_num.now_num\nFROM\n	(\n		SELECT\n			timetype_table.where_time AS where_time,\n			timetype_table.group_time AS group_time,\n			pre_salesorder.quantity AS pre_num,\n			now_salesorder.quantity AS now_num\n		FROM\n			(\n				SELECT\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							YEAR (NOW())\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							QUARTER (NOW())\n						ELSE\n							YEAR (NOW())\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n							MONTH (date)\n						WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n							QUARTER (date)\n						WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n							MONTH (date)\n						ELSE\n							MONTH (date)\n						END\n					) AS group_time\n				FROM\n					tmp_date a\n				WHERE\n					date LIKE \'%2023%\'\n				GROUP BY\n					group_time\n			) timetype_table\n		LEFT JOIN (\n			SELECT\n				now_s_detail.id AS out_id,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (ld_outboundorder.outdate)\n					ELSE\n						YEAR (ld_outboundorder.outdate)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					ELSE\n						MONTH (ld_outboundorder.outdate)\n					END\n				) AS group_time,\n				sum(now_s_detail.tax_amount) AS tax_amount,\n				sum(now_s_detail.quantity) AS quantity\n			FROM\n				ld_outboundorder\n			LEFT JOIN ld_outboundorderdetail now_s_detail ON now_s_detail.id = ld_outboundorder.out_id\n			LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.smownerid,\n				\'{userscope}\'\n			)\n			AND (\n				ld_outboundorder.outdate BETWEEN \'{starttime}\'\n				AND \'{endtime}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) now_salesorder ON now_salesorder.where_time = timetype_table.where_time\n		AND now_salesorder.group_time = timetype_table.group_time\n		LEFT JOIN (\n			SELECT\n				pre_s_detail.id AS out_id,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 YEAR\n							)\n						)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						QUARTER (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 YEAR\n							)\n						)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'本年和去年-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本年和去年-按季度\' THEN\n						QUARTER (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'本季度和上季度-按月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					ELSE\n						MONTH (ld_outboundorder.outdate)\n					END\n				) AS group_time,\n				sum(pre_s_detail.tax_amount) AS tax_amount,\n				sum(pre_s_detail.quantity) AS quantity\n			FROM\n				ld_outboundorder\n			LEFT JOIN ld_outboundorderdetail pre_s_detail ON pre_s_detail.id = ld_outboundorder.out_id\n			LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.smownerid,\n				\'{userscope}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) pre_salesorder ON pre_salesorder.where_time = timetype_table.where_time\n		AND pre_salesorder.group_time = timetype_table.group_time\n		GROUP BY\n			timetype_table.group_time\n	) p_num\nGROUP BY\n	p_num.group_time','Default',NULL,NULL,'product_outboundorder_quantity_y_to_y'),(314,'产品出库金额同比','','sqlch