  `fieldname` varchar(100) DEFAULT NULL COMMENT '下拉框值来源字段',
  `selectvalues` text COMMENT '下拉框值列表 以逗号隔开',
  `sequence` int(4) DEFAULT NULL COMMENT '排序',
  `filter_relatedtab` varchar(200) DEFAULT NULL,
  `uses` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8;
