CREATE TABLE `ld_customview` (
  `cvid` int(19) NOT NULL,
  `viewname` varchar(100) NOT NULL,
  `setdefault` int(1) DEFAULT '0',
  `setmetrics` int(1) DEFAULT '0',
  `entitytype` varchar(50) DEFAULT NULL,
  `status` int(1) DEFAULT '1',
  `userid` int(19) DEFAULT '1',
  `sequence` int(19) DEFAULT NULL,
  `pagewidthpercent` int(11) DEFAULT NULL,
  `customcategory` varchar(25) DEFAULT NULL,
  `description` varchar(100) DEFAULT NULL,
  `pool_id` int(11) DEFAULT '0',
  `groupid` int(19) DEFAULT '0',
  `icon_path` text,
  PRIMARY KEY (`cvid`),
  KEY `customview_entitytype_idx` (`entitytype`) USING BTREE,
  KEY `userid_idx` (`userid`) USING BTREE,
  KEY `setmetrics` (`setmetrics`) USING BTREE,
  CONSTRAINT `ld_customview_ibfk_1` FOREIGN KEY (`entitytype`) REFERENCES `ld_tab` (`name`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

