INSERT INTO `ld_field_formula` VALUES (1,5723,NULL,'servicecontracts_end_date','Max','2023-05-24 03:52:59','2023-05-24 03:52:59'),(3,1308,'SELECT ldcrm_digitformat({a}*0.01*(CASE WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type = 205)=1 THEN {b} ELSE {c} END ),\'金额\') AS tmp_value;','{formulavar:[{\'lettervar\':\'a\',\'column\':\'possibility\'},{\'lettervar\':\'b\',\'column\':\'amount\'},{\'lettervar\':\'c\',\'column\':\'total\'}]}','sql','2023-12-12 10:06:37','2023-12-12 10:06:37'),(6,8080,'a+b+c','{formulavar:[{\'lettervar\':\'a\',\'column\':\'basic_pay\'},{\'lettervar\':\'b\',\'column\':\'performance_pay\'},{\'lettervar\':\'c\',\'column\':\'overtime_pay\'}]}','','2024-05-06 03:57:49','2024-05-06 03:57:49'),(7,8084,'a+b+c','{formulavar:[{\'lettervar\':\'a\',\'column\':\'phone_allowance\'},{\'lettervar\':\'b\',\'column\':\'traffic_allowance\'},{\'lettervar\':\'c\',\'column\':\'meal_allowance\'}]}','','2024-05-06 03:57:49','2024-05-06 03:57:49'),(8,8089,'a+b+c+d','{formulavar:[{\'lettervar\':\'a\',\'column\':\'absence_deduction\'},{\'lettervar\':\'b\',\'column\':\'late_deduction\'},{\'lettervar\':\'c\',\'column\':\'personal_deduction\'},{\'lettervar\':\'d\',\'column\':\'sick_deduction\'}]}','','2024-05-06 03:57:49','2024-05-06 03:57:49'),(11,8101,'a+b+c+d+e+f','{formulavar:[{\'lettervar\':\'a\',\'column\':\'babycare_deduction\'},{\'lettervar\':\'b\',\'column\':\'child_education_deduction\'},{\'lettervar\':\'c\',\'column\':\'continue_education_deduction\'},{\'lettervar\':\'d\',\'column\':\'elderly_deduction\'},{\'lettervar\':\'e\',\'column\':\'house_loan_deduction\'},{\'lettervar\':\'f\',\'column\':\'house_rental_deduction\'}]}','','2024-05-06 03:57:58','2024-05-06 03:57:58'),(12,8091,'a*b*0.01','{formulavar:[{\'lettervar\':\'a\',\'column\':\'social_base\'},{\'lettervar\':\'b\',\'column\':\'medical_rate\'}]}','','2024-05-06 03:57:58','2024-05-06 03:57:58'),(13,8090,'a*b*0.01','{formulavar:[{\'lettervar\':\'a\',\'column\':\'social_base\'},{\'lettervar\':\'b\',\'column\':\'endowment_rate\'}]}','','2024-05-06 03:57:58','2024-05-06 03:57:58'),(14,8092,'a*b*0.01','{formulavar:[{\'lettervar\':\'a\',\'column\':\'social_base\'},{\'lettervar\':\'b\',\'column\':\'unemployment_rate\'}]}','','2024-05-06 03:57:58','2024-05-06 03:57:58'),(15,8094,'a*b*0.01','{formulavar:[{\'lettervar\':\'a\',\'column\':\'social_base\'},{\'lettervar\':\'b\',\'column\':\'house_rate\'}]}','','2024-05-06 03:57:58','2024-05-06 03:57:58'),(17,8095,'a+b+c+d+e*f*0.01','{formulavar:[{\'lettervar\':\'a\',\'column\':\'endowment_insurance\'},{\'lettervar\':\'b\',\'column\':\'medical_insurance\'},{\'lettervar\':\'c\',\'column\':\'unemployment_insurance\'},{\'lettervar\':\'d\',\'column\':\'injury_insurance\'},{\'lettervar\':\'e\',\'column\':\'house_base\'},{\'lettervar\':\'f\',\'column\':\'house_rate\'}]}','','2024-05-06 03:57:58','2024-05-06 03:57:58'),(18,8058,'a-b-c','{formulavar:[{\'lettervar\':\'a\',\'column\':\'payable_subtotal\'},{\'lettervar\':\'b\',\'column\':\'attendance_subtotal\'},{\'lettervar\':\'c\',\'column\':\'insurance_subtotal\'}]}','','2024-05-06 03:57:58','2024-05-06 03:57:58'),(19,8060,'SELECT\r\n	CASE\r\n		WHEN yingna_total<=0 THEN 0.00\r\n		WHEN yingna_total<36000 THEN ROUND(yingna_total*0.03-yina_total,2)\r\n		WHEN yingna_total<144000 THEN ROUND(yingna_total*0.1-2520-yina_total,2)\r\n		WHEN yingna_total<300000 THEN ROUND(yingna_total*0.2-16920-yina_total,2)\r\n		WHEN yingna_total<420000 THEN ROUND(yingna_total*0.25-31920-yina_total,2)\r\n		WHEN yingna_total<660000 THEN ROUND(yingna_total*0.3-52920-yina_total,2)\r\n		WHEN yingna_total<960000 THEN ROUND(yingna_total*0.35-85920-yina_total,2)\r\n		WHEN yingna_total>=960000 THEN ROUND(yingna_total*0.45-181920-yina_total,2)\r\n	END AS tmp_value\r\nFROM (\r\n	SELECT\r\n		SUM(yingna_total)+\'{c}\'-\'{d}\'-\'{e}\' AS yingna_total,\r\n		SUM(yina_total) AS yina_total\r\n	FROM (\r\n		SELECT\r\n			SUM(IFNULL(pretax_salary_total,0)-IFNULL(insurance_subtotal,0)-IFNULL(additional_subtotal,0)-IFNULL(tax_startpoint,0)) AS yingna_total,\r\n			SUM(IFNULL(individual_income_tax,0)) AS yina_total\r\n		FROM ld_salary\r\n		WHERE deleted=0\r\n			AND approvestatus<>\'已拒绝\'\r\n			AND LEFT(salary_period,4)=LEFT(\'{a}\',4)\r\n			AND RIGHT(salary_period,2)<RIGHT(\'{a}\',2)\r\n			AND smownerid=\'{b}\'\r\n		UNION\r\n		SELECT 0 AS yingna_total,0 AS yina_total\r\n	) a\r\n) a','{formulavar:[{\'lettervar\':\'a\',\'column\':\'salary_period\'},{\'lettervar\':\'b\',\'column\':\'smownerid\'},{\'lettervar\':\'c\',\'column\':\'pretax_salary_total\'},{\'lettervar\':\'d\',\'column\':\'tax_startpoint\'},{\'lettervar\':\'e\',\'column\':\'additional_subtotal\'}]}','sql','2024-05-06 03:57:58','2024-05-06 03:57:58'),(21,8059,'a-b+c','{formulavar:[{\'lettervar\':\'a\',\'column\':\'pretax_salary_total\'},{\'lettervar\':\'b\',\'column\':\'individual_income_tax\'},{\'lettervar\':\'c\',\'column\':\'otherpayable_subtotal\'}]}','','2024-06-25 08:19:32','2024-06-25 08:19:32'),(22,8257,'SELECT 0+\'{a}\'+\'{b}\'+\'{c}\'+\'{d}\'+\'{e}\'+\'{f}\'+\'{g}\'+\'{h}\'+\'{i}\'+\'{j}\' as tmp_value','{formulavar:[{\'lettervar\':\'a\',\'column\':\'global_awareness\'},{\'lettervar\':\'b\',\'column\':\'collaboration_awareness\'},{\'lettervar\':\'c\',\'column\':\'service_awareness\'},\n       {\'lettervar\':\'d\',\'column\':\'communication_ability\'},{\'lettervar\':\'e\',\'column\':\'business_ability\'},{\'lettervar\':\'f\',\'column\':\'planning_ability\'},\n       {\'lettervar\':\'g\',\'column\':\'innovation_ability\'},{\'lettervar\':\'h\',\'column\':\'principality\'},{\'lettervar\':\'i\',\'column\':\'responsibility\'},{\'lettervar\':\'j\',\'column\':\'morality\'}]}','sql','2024-06-25 08:19:36','2024-06-25 08:19:36');
