DROP TABLE IF EXISTS `ld_modentity_num`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_modentity_num` (
  `num_id` int(19) NOT NULL,
  `semodule` varchar(50) NOT NULL,
  `prefix` varchar(50) NOT NULL DEFAULT '',
  `start_id` varchar(50) NOT NULL,
  `cur_id` varchar(50) NOT NULL,
  `active` varchar(2) NOT NULL,
  `datetype` varchar(20) DEFAULT NULL,
  `UseUserAccount` int(11) DEFAULT '0',
  `isallow` int(11) DEFAULT '0',
  `prefixtype` int(11) DEFAULT '0',
  `reset_value` varchar(50) DEFAULT 'no',
  `complement` int(11) DEFAULT '0',
  PRIMARY KEY (`num_id`),
  UNIQUE KEY `num_idx` (`num_id`) USING BTREE,
  KEY `semodule_active_idx` (`semodule`,`active`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

