l\r\nINNER JOIN ld_account ON ld_account.accountid = ld_potential.accountid\r\nWHERE ld_account.deleted = 0 AND ld_potential.potentialid = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_troubletickets\r\nINNER JOIN ld_account ON ld_account.accountid = ld_troubletickets.accountid\r\nWHERE ld_account.deleted = 0 AND ld_troubletickets.ticketid = ?\r\nUNION \r\nSELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS address\r\nFROM ld_project\r\nINNER JOIN ld_account ON ld_account.accountid = ld_project.accountid\r\nWHERE ld_account.deleted = 0 AND ld_project.projectid = ?\nUNION\nSELECT CONCAT(ld_leads.bill_state,ld_leads.bill_city,IFNULL(ld_leads.bill_area,\"\"),ld_leads.bill_street) AS address\nFROM ld_leads\nWHERE deleted = 0 AND leadsid = ?','no'),(208,48,22,0,NULL,0,1,54,'all',NULL,5,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(209,48,37,0,1,0,2,54,'all',NULL,5,0,0,0,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(210,169,22,0,0,0,1,168,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(211,169,37,0,0,0,2,168,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(212,169,2,1,0,0,3,168,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(213,170,22,0,0,0,1,169,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(214,170,37,0,0,0,2,169,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,NULL,NULL,'no'),(215,170,2,1,0,0,3,169,'all',NULL,5,0,0,0,'no',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL