INSERT INTO `ld_organizationdetails_product` VALUES (1,1,'标准版','管控销售流程助你增加销售业绩|100人以内的销售团队|500人以内的中型企业','https://weixin-1255564871.cos.ap-shanghai.myqcloud.com/web_51mis/mob92/images/p_biaozhun.png',8),(2,1,'企业版','覆盖企业管理五大需求，实现多种需求|销售团队100人以上的大型集团企业使用','https://weixin-1255564871.cos.ap-shanghai.myqcloud.com/web_51mis/mob92/images/p_qiye.png',6),(3,1,'基础版','简单易操作|20人以内的销售团队|100人以内的中小型企业','https://weixin-1255564871.cos.ap-shanghai.myqcloud.com/web_51mis/mob92/images/p_jichu.png',6),(4,1,'进销存','集销售、采购、库存管理为一体的进销存管理专家|500人以内的中型企业','https://weixin-1255564871.cos.ap-shanghai.myqcloud.com/web_51mis/mob92/images/p_jinxiaocun.png',7);
