  PRIMARY KEY (`id`),
  KEY `picklist_values_listid` (`listid`) USING BTREE,
  KEY `picklist_values_sequence` (`sequence`) USING BTREE,
  KEY `listvalue` (`listvalue`)
) ENGINE=InnoDB AUTO_INCREMENT=22812 DEFAULT CHARSET=utf8;
