--
-- Table structure for table `ld_project`
--

DROP TABLE IF EXISTS `ld_project`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_project` (
  `projectid` int(11) NOT NULL DEFAULT '0',
  `projectname` varchar(255) DEFAULT NULL,
  `project_no` varchar(100) DEFAULT NULL,
  `startdate` date DEFAULT NULL,
  `targetenddate` date DEFAULT NULL,
  `actualenddate` date DEFAULT NULL,
  `targetbudget` decimal(25,2) DEFAULT NULL,
  `projecturl` varchar(255) DEFAULT NULL,
  `projectstatus` varchar(100) DEFAULT NULL,
  `projectpriority` varchar(100) DEFAULT NULL,
  `projecttype` varchar(100) DEFAULT NULL,
  `progress` varchar(100) DEFAULT NULL,
  `linktoaccountscontacts` varchar(100) DEFAULT NULL,
  `accountid` int(11) DEFAULT '0',
  `contactid` int(11) DEFAULT '0',
  `approvestatus` varchar(200) DEFAULT '未提交',
  `approveby` int(1) DEFAULT NULL,
  `salesorderid` int(11) DEFAULT '0',
  `potentialid` int(11) DEFAULT '0',
  `smownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `description` text,
  `deleted` int(11) DEFAULT '0',
  `realprojectcost` decimal(25,2) DEFAULT '0.00',
  `costbudget` decimal(25,2) DEFAULT NULL,
  `timebudget` decimal(25,2) DEFAULT NULL,
  `hascost` decimal(25,2) DEFAULT '0.00',
  `hastime` decimal(25,2) DEFAULT '0.00',
  `completetask` varchar(100) DEFAULT NULL,
  `entitytype` varchar(25) DEFAULT NULL,
  `currentapprover` varchar(1000) DEFAULT NULL,
  `print_times` int(11) DEFAULT '0',
  `approvetime` datetime DEFAULT NULL,
  `advance_stage` varchar(100) DEFAULT NULL,
  `approvesubmitter` int(19) DEFAULT '0',
  `approvesubmittedtime` datetime DEFAULT NULL,
  `approveurgent` varchar(10) DEFAULT 'no',
  `approveexpediting` varchar(10) DEFAULT 'no',
  `currentapprovestepid` int(19) DEFAULT '0',
  `sign_longtitude` varchar(200) DEFAULT NULL,
  `sign_latitude` varchar(200) DEFAULT NULL,
  `sign_location_address` varchar(200) DEFAULT NULL,
  `team_memberid` text,
  `tag` varchar(50) DEFAULT NULL,
  `balance_hours` decimal(25,2) DEFAULT NULL,
  `balance_fee` decimal(25,2) DEFAULT NULL,
  `signin_address` varchar(5) DEFAULT NULL,
  `kis_id` varchar(200) DEFAULT NULL,
  `kis_no` varchar(200) DEFAULT NULL,
  `exchtime` datetime DEFAULT NULL,
  `exchmsg` text,
  `latestpushtime` datetime DEFAULT NULL,
  `end_accountid` int(19) DEFAULT '0',
  PRIMARY KEY (`projectid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

