/*!40000 ALTER TABLE `ld_projecttask` ENABLE KEYS */;
UNLOCK TABLES;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `reset_projecttaskinfo_before_projecttaskt_insert` BEFORE INSERT ON `ld_projecttask` FOR EACH ROW BEGIN

	IF @disable_triggers IS NULL THEN
		SET NEW.balance_hours=ROUND(IFNULL(NEW.timebudget,0)-IFNULL(NEW.hastime,0),2);
		SET NEW.balance_fee=ROUND(IFNULL(NEW.costbudget,0)-IFNULL(NEW.hascost,0),2);

		IF NEW.projecttaskstatus='已完成'  THEN
			SET NEW.actualenddate=CURDATE();
		END IF;

		IF IFNULL(NEW.timebudget,0)=0 THEN
			SET NEW.projecttaskprogress='100%';
		ELSE
			SET NEW.projecttaskprogress=CONCAT(ROUND(IFNULL(NEW.hastime,0)*100/IFNULL(NEW.timebudget,0),2),'%');
		END IF;
	END IF;

END */;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `update_projecttask_distributetime` BEFORE UPDATE ON `ld_projecttask` FOR EACH ROW BEGIN 
		


	IF @disable_triggers IS NULL THEN
		IF new.smownerid>0 and new.smownerid<>old.smownerid THEN
				SET NEW.distributetime=now();
		END IF;

		SET NEW.balance_hours=ROUND(IFNULL(NEW.timebudget,0)-IFNULL(NEW.hastime,0),2);
		SET NEW.balance_fee=ROUND(IFNULL(NEW.costbudget,0)-IFNULL(NEW.hascost,0),2);

		IF NEW.projecttaskstatus='已完成' AND IFNULL(OLD.projecttaskstatus,'')<>'已完成' THEN
			SET NEW.actualenddate=CURDATE();
		END IF;


		IF IFNULL(NEW.timebudget,0)=0 THEN
			SET NEW.projecttaskprogress='100%';
		ELSE
			SET NEW.projecttaskprogress=CONCAT(ROUND(IFNULL(NEW.hastime,0)*100/IFNULL(NEW.timebudget,0),2),'%');
		END IF;

	END IF;

END */;;
