DROP TABLE IF EXISTS `ld_reminds_accepted`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_reminds_accepted` (
  `remindsid` int(19) NOT NULL DEFAULT '0',
  `content` text,
  `date_time` datetime DEFAULT NULL,
  `recieverid` int(19) DEFAULT NULL,
  `status_rmd` varchar(50) DEFAULT '未读',
  `related_to` int(19) NOT NULL,
  `reltab` varchar(100) DEFAULT NULL,
  `is_del_send` int(1) DEFAULT '0',
  `is_del_rec` int(1) DEFAULT '0',
  `reminds_ruleid` int(11) DEFAULT '0',
  `smownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `description` text,
  `deleted` int(11) DEFAULT '0',
  `push_to_weixin` int(1) DEFAULT '2',
  `push_to_ding` int(11) DEFAULT '2' COMMENT '钉钉提醒发送标识',
  `push_time` datetime DEFAULT NULL,
  `push_time_ding` datetime DEFAULT NULL COMMENT '钉钉提醒发送时间',
  `remindstype` varchar(200) DEFAULT NULL,
  `wxremindstype` varchar(100) DEFAULT NULL,
  `parentid` int(19) DEFAULT '0',
  `push_to_yzj` int(11) DEFAULT '2' COMMENT '云之家提醒发送标识',
  `push_time_yzj` datetime DEFAULT NULL COMMENT '云之家提醒发送时间',
  `team_memberid` text,
  `readedtime` datetime DEFAULT NULL,
  `tag` varchar(50) DEFAULT NULL,
  `push_to_wxselfbuilt` int(11) DEFAULT '2' COMMENT '企业微信自建应用提醒发送标识',
  `push_time_wxselfbuilt` datetime DEFAULT NULL COMMENT '企业微信自建应用提醒发送时间',
  `push_to_offiaccount` int(2) DEFAULT '2',
  `push_time_offiaccount` datetime DEFAULT NULL,
  `push_to_fw` int(11) DEFAULT '2' COMMENT '泛微提醒发送标识',
  `push_time_fw` datetime DEFAULT NULL COMMENT '泛微提醒发送时间',
  `push_to_nativeapp` int(2) DEFAULT '2',
  `push_time_nativeapp` datetime DEFAULT NULL,
  `push_to_zy` int(11) DEFAULT '2' COMMENT '提醒发送标识',
  `push_time_zy` datetime DEFAULT NULL COMMENT '提醒发送时间',
  `push_to_td` tinyint(2) DEFAULT '0',
  `push_time_td` datetime DEFAULT NULL,
  PRIMARY KEY (`remindsid`),
  KEY `related_to` (`related_to`) USING BTREE,
  KEY `reminds_ruleid` (`reminds_ruleid`) USING BTREE,
  KEY `recieverid` (`recieverid`),
  KEY `smownerid` (`smownerid`),
  KEY `smcreatorid` (`smcreatorid`),
  KEY `date_time` (`date_time`),
  KEY `reminds_accepted_deleted_is_del_rec_status_rmd` (`deleted`,`is_del_rec`,`status_rmd`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
