  `subtotal` decimal(25,8) DEFAULT NULL,
  `nosendpayment` decimal(20,2) DEFAULT '0.00',
  `bankaccountsetid` int(11) DEFAULT NULL,
  `checkoutstatus` varchar(25) DEFAULT '未审核',
  `checker` int(19) DEFAULT NULL,
  `smownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `deleted` int(11) DEFAULT '0',
  `description` text,
  `currency_id` int(1) DEFAULT '1',
  `conversion_rate` decimal(25,6) DEFAULT '1.000000',
  `currency_symbol` varchar(30) DEFAULT '¥',
  `approveby` int(19) DEFAULT '0',
  `approvestatus` varchar(200) DEFAULT '未提交',
  `currentapprover` varchar(1000) DEFAULT NULL,
  `bank_accountname` varchar(200) DEFAULT NULL,
  `bank_accountnum` varchar(200) DEFAULT NULL,
  `bank_opening` varchar(200) DEFAULT NULL,
  `corporatename` varchar(200) DEFAULT NULL,
