DROP TABLE IF EXISTS `ld_troubletickets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_troubletickets` (
  `ticketid` int(19) NOT NULL,
  `ticket_no` varchar(100) NOT NULL,
  `groupname` varchar(100) DEFAULT NULL,
  `product_id` int(19) DEFAULT NULL,
  `priority` varchar(200) DEFAULT NULL,
  `severity` varchar(200) DEFAULT NULL,
  `status` varchar(200) DEFAULT NULL,
  `category` varchar(200) DEFAULT NULL,
  `ticket_title` varchar(200) DEFAULT NULL,
  `solution` text,
  `update_log` text,
  `version_id` int(11) DEFAULT NULL,
  `hours` varchar(200) DEFAULT NULL,
  `days` varchar(200) DEFAULT NULL,
  `from_portal` varchar(3) DEFAULT NULL,
  `servicetype` varchar(50) DEFAULT NULL,
  `consumetime` varchar(50) DEFAULT NULL,
  `hopetime` datetime DEFAULT NULL,
  `realtime` datetime DEFAULT NULL,
  `approvestatus` varchar(200) DEFAULT '未提交',
  `approveby` int(19) DEFAULT '0',
  `accountid` int(11) DEFAULT '0',
  `contactid` int(11) DEFAULT '0',
  `salesorderid` int(19) DEFAULT NULL,
  `servicecontractsid` int(11) DEFAULT NULL,
  `smownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `deleted` int(11) DEFAULT '0',
  `description` text,
  `fees` decimal(25,8) DEFAULT NULL,
  `productcategory` varchar(200) DEFAULT NULL,
  `traficfee` decimal(25,8) DEFAULT NULL,
  `beizhu` text,
  `potentialid` int(19) DEFAULT NULL,
  `questionid` text,
  `hopetime_end` datetime DEFAULT NULL,
  `hope_address` varchar(500) DEFAULT NULL,
  `bw8_datetime` datetime DEFAULT NULL,
  `distributetime` datetime DEFAULT NULL,
  `bw8_id` int(11) DEFAULT '0',
  `currentapprover` varchar(1000) DEFAULT NULL,
  `print_times` int(11) DEFAULT '0',
  `approvetime` datetime DEFAULT NULL,
  `locationaddress` varchar(255) DEFAULT NULL,
  `sourcefrom` varchar(100) DEFAULT 'crm',
  `locationaddress_map` varchar(20) DEFAULT NULL,
  `projectid` int(19) DEFAULT '0',
  `longtitude` varchar(255) DEFAULT NULL,
  `latitude` varchar(255) DEFAULT NULL,
  `location_address` varchar(255) DEFAULT NULL,
  `customer_signature` varchar(200) DEFAULT NULL,
  `advance_stage` varchar(100) DEFAULT NULL,
  `approvesubmitter` int(19) DEFAULT '0',
  `approvesubmittedtime` datetime DEFAULT NULL,
  `approveurgent` varchar(10) DEFAULT 'no',
  `approveexpediting` varchar(10) DEFAULT 'no',
  `currentapprovestepid` int(19) DEFAULT '0',
  `sign_longtitude` varchar(200) DEFAULT NULL,
  `sign_latitude` varchar(200) DEFAULT NULL,
  `sign_location_address` varchar(200) DEFAULT NULL,
  `team_memberid` text,
  `tag` varchar(50) DEFAULT NULL,
  `signin_address` varchar(5) DEFAULT NULL,
  `kis_id` varchar(200) DEFAULT NULL,
  `kis_no` varchar(200) DEFAULT NULL,
  `exchtime` datetime DEFAULT NULL,
  `exchmsg` text,
  `latestpushtime` datetime DEFAULT NULL,
  PRIMARY KEY (`ticketid`),
  KEY `troubletickets_status_idx` (`status`) USING BTREE,
