/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `up_faq_pinci2` AFTER UPDATE ON `ld_troubletickets` FOR EACH ROW BEGIN

IF @disable_triggers IS NULL THEN 

	IF length(new.questionid)>0 THEN
			call up_faq_byid(new.questionid);
	END IF;

	
	IF length(old.questionid)>0 and old.questionid<>new.questionid THEN
			call up_faq_byid(new.questionid);
	END IF;

END IF;

END */;;
DELIMITER ;
