/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_reset_approvenew` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_reset_approvenew`(
	tmp_modulename VARCHAR(100)
)
BEGIN
	SET @mytabid=(SELECT tabid FROM ld_tab WHERE `name`=tmp_modulename);
	IF NOT EXISTS (SELECT 1 FROM ld_approve WHERE tabid=@mytabid AND isnewapprove='yes') THEN

		DELETE FROM ld_approvestep WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid);
		DELETE FROM ld_approve2role WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid);
		DELETE FROM ld_approve2user WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid);
		DELETE FROM ld_approvecanceladvfilter WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid);
		DELETE FROM ld_approvecanceladvfilter_grouping WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid);
		DELETE FROM ld_approvereminds WHERE stepid IN (SELECT id FROM ld_approvestep WHERE approveid IN (SELECT id FROM ld_approve WHERE tabid=@mytabid));
		DELETE FROM ld_approve WHERE tabid=@mytabid;

		SET @max_approveid=(SELECT MAX(id) FROM ld_approve);
		SET @max_seq=(SELECT MAX(sequence) FROM ld_approve);
		SET @zh_modulename=(SELECT fieldlabel FROM ld_tranlabel WHERE tabid=@mytabid AND Relateid=@mytabid AND trantable='ld_tab' AND languagetype='zh' LIMIT 1);
		INSERT INTO ld_approve(
			id,
			tabid,
			name,
			status,
			smcreatorid,

			modifiedby,
			createdtime,
			modifiedtime,
			allowediting,
			finishedallowedit,

			default_on_new,
			default_on_submit,
			allowagainsubmit,
			finishedfield_allocatetype,
			isnewapprove,

			sequence
		)
		SELECT 
			@max_approveid+1,
			@mytabid,
			CONCAT(@zh_modulename,'预置审批流程'),
			0,
			1,

			1,
			NOW(),
			NOW(),
			0,
			'no',

			'yes',
			'yes',
			'no',
			'all',
			'yes',

			@max_seq+1;

		UPDATE ld_approve_seq SET id=(SELECT MAX(id) FROM ld_approve);

		INSERT INTO ld_approve2user(approveid,userid) SELECT @max_approveid+1,-1;

		SET @max_stepid=(SELECT MAX(id) FROM ld_approvestep);
		INSERT INTO ld_approvestep(
			id,
			approveid,
			name,
			ended,
			step,

			sequence,
			createdtime,
			modifiedtime,
			approvetype,
			specifyapproverid,
			
			alloweditbill,
			steptype,
			isnewstep,
			flowstepid,
			childids,

			branchflowstepid
		)
		SELECT
			@max_stepid+1,
			@max_approveid+1,
			'开始',
			NULL,
			NULL,

			1,
			NULL,
			NULL,
			NULL,
			1,
			
			NULL,
			'start',
			'yes',
			-1,
			1,

			-1;

		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+1,
			0,
			'dialog',
			'approver',
			'有新的{modulelabel}需要审批，请及时处理！',

			NULL,
			NULL,
			'【{modulelabel}】审批通知';


		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+1,
			1,
			'dialog',
			'smowner',
			'您负责的{modulelabel}已通过审批步骤{step}',

			NULL,
			NULL,
			'【{modulelabel}】审批结果通知';

		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+1,
			2,
			'dialog',
			'smowner',
			'您负责的{modulelabel}未通过审批步骤{step}，原因：{description}',

			NULL,
			NULL,
			'【{modulelabel}】审批结果通知';

		INSERT INTO ld_approvestep(
			id,
			approveid,
			name,
			ended,
			step,

			sequence,
			createdtime,
			modifiedtime,
			approvetype,
			specifyapproverid,
			
			alloweditbill,
			steptype,
			isnewstep,
			flowstepid,
			childids,
			
			branchflowstepid
		)
		SELECT
			@max_stepid+2,
			@max_approveid+1,
			'一级审批',
			0,
			1,

			1,
			NOW(),
			NOW(),
			6,
			1,

			'no',
			'approver',
			'yes',
			1,
			NULL,
			
			-1;

		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+2,
			0,
			'dialog',
			'approver',
			'有新的{modulelabel}需要审批，请及时处理！',

			NULL,
			NULL,
			'【{modulelabel}】审批通知';


		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+2,
			1,
			'dialog',
			'smowner',
			'您负责的{modulelabel}已通过审批步骤{step}',

			NULL,
			NULL,
			'【{modulelabel}】审批结果通知';

		INSERT INTO ld_approvereminds(
			stepid,
			type,
			remindmethod,
			reminduser,
			remindcontent,

			reminduserid,
			remindcolumnname,
			remindtitle
		)
		SELECT 
			@max_stepid+2,
			2,
			'dialog',
			'smowner',
			'您负责的{modulelabel}未通过审批步骤{step}，原因：{description}',

			NULL,
			NULL,
			'【{modulelabel}】审批结果通知';

		UPDATE ld_approvestep_seq SET id=(SELECT MAX(id) FROM ld_approvestep);

	END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_reset_expensebudget_byid` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_reset_expensebudget_byid`(
	tmp_mybillid TEXT
)
BEGIN

	DECLARE tmp_budgettype VARCHAR(100) DEFAULT '';
	DECLARE tmp_budgetindicators VARCHAR(100) DEFAULT '';
	
	DECLARE MY_RESETCUSOR CURSOR FOR 
					SELECT
						a.expensebudget_type,
						a.budget_indicators
					FROM ld_expensebudget a
					WHERE FIND_IN_SET(a.expensebudgetid,tmp_mybillid)
						AND a.expensebudget_type IN ('salesGoalBudget','salesAchievementBudget')
					GROUP BY a.expensebudget_type,a.budget_indicators;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_budgettype = NULL;

	OPEN MY_RESETCUSOR; 
	FETCH MY_RESETCUSOR INTO tmp_budgettype,tmp_budgetindicators;
	WHILE(tmp_budgettype IS NOT NULL) DO
		SET @exec_resetbudgetinfo='';
		IF tmp_budgettype ='salesGoalBudget' THEN
			SET @exec_resetbudgetinfo=(
				SELECT
					CONCAT("UPDATE ld_expensebudget a ","\r\n",
						"LEFT JOIN ld_expensebudgetdetail b ON b.id=a.expensebudgetid ","\r\n",
						"SET ","\r\n",
						"	b.reference_amount=","IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ld_salestarget WHERE userid=b.lin_users_id AND CONCAT(targetyear,'-',targetmouth,'-01') BETWEEN a.indicators_start_date AND a.indicators_end_date),0),","\r\n",
						"	b.amount=IFNULL(b.budget_rate,0)*0.01*","IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ld_salestarget WHERE userid=b.lin_users_id AND CONCAT(targetyear,'-',targetmouth,'-01') BETWEEN a.indicators_start_date AND a.indicators_end_date),0),","\r\n",
						"	b.budget_amount=IFNULL(b.adjustment_amount,0)+IFNULL(b.budget_rate,0)*0.01*","IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ld_salestarget WHERE userid=b.lin_users_id AND CONCAT(targetyear,'-',targetmouth,'-01') BETWEEN a.indicators_start_date AND a.indicators_end_date),0)","\r\n",
						"WHERE FIND_IN_SET(a.expensebudgetid,'",tmp_mybillid,"') ","\r\n",
							"	AND a.expensebudget_type='salesGoalBudget' ","\r\n",
							"	AND a.budget_indicators='",tmp_budgetindicators,"'"
						) AS exex_sql
				FROM (
					SELECT 
						`name` AS indicators_type,
						`columns` AS budget_column 
					FROM ld_expensebudget_totalcolumns 
					WHERE type='salesGoalBudget' 
					GROUP BY `name`
				) a
				WHERE a.indicators_type=tmp_budgetindicators
			);
		ELSE
			SET @exec_resetbudgetinfo=(
				SELECT
					CONCAT("UPDATE ld_expensebudget a ","\r\n",
						"LEFT JOIN ld_expensebudgetdetail b ON b.id=a.expensebudgetid ","\r\n",
						"SET ","\r\n",
						"	b.reference_amount=(",total_sql,"),","\r\n",
						"	b.amount=IFNULL(b.budget_rate,0)*0.01*(",total_sql,"),","\r\n",
						"	b.budget_amount=IFNULL(b.adjustment_amount,0)+IFNULL(b.budget_rate,0)*0.01*(",total_sql,")","\r\n",
						"WHERE FIND_IN_SET(a.expensebudgetid,'",tmp_mybillid,"') ","\r\n",
							"	AND a.expensebudget_type='salesAchievementBudget' ","\r\n",
							"	AND a.budget_indicators='",tmp_budgetindicators,"'"
						) AS exex_sql
				FROM (
					SELECT
						indicators_type,
						budget_column,
						modulename,
						GROUP_CONCAT(CONCAT("IFNULL((SELECT SUM(",IFNULL(a.budget_column,''),") FROM ",(SELECT CONCAT(main_tablename,' LEFT JOIN ',custom_tablename,' ON ',main_tablename,'.',primary_key,'=',custom_tablename,'.',primary_key ) FROM ld_tab WHERE `name`=a.modulename)," WHERE deleted=0 AND (CASE WHEN '",a.approved,"'='yes' THEN approvestatus='已批准' ELSE 1=1 END) AND approvestatus<>'已拒绝' AND smownerid=b.lin_users_id AND ",a.time_condition," BETWEEN a.indicators_start_date AND a.indicators_end_date),0)") SEPARATOR '+') AS total_sql
					FROM (
						SELECT 
							`name` AS indicators_type,
							`columns` AS budget_column,
							modulename,
							CASE
								WHEN EXISTS (SELECT 1 FROM ld_field WHERE tablename=LEFT(time_condition_field,LOCATE('.',time_condition_field)-1) AND columnname=RIGHT(time_condition_field,LENGTH(time_condition_field)-LOCATE('.',time_condition_field)) AND presence<>1) THEN time_condition_field
								ELSE time_condition_default
							END AS time_condition,
							approved
						FROM ld_expensebudget_totalcolumns 
						WHERE type='salesAchievementBudget' 
						GROUP BY `name`,`columns`
					) a
					GROUP BY indicators_type
				) a
				WHERE a.indicators_type=tmp_budgetindicators
			);
		END IF;
		
		IF IFNULL(@exec_resetbudgetinfo,'')<>'' THEN
			SET @disable_triggers=1;
			PREPARE resetbudgetinfostmt FROM @exec_resetbudgetinfo;
			EXECUTE resetbudgetinfostmt;
			DEALLOCATE PREPARE resetbudgetinfostmt;
			SET @disable_triggers=NULL;
		END IF;
		FETCH MY_RESETCUSOR INTO tmp_budgettype,tmp_budgetindicators;
	END WHILE;
	CLOSE MY_RESETCUSOR;
	
	UPDATE ld_expensebudget SET total=(SELECT SUM(budget_amount) FROM ld_expensebudgetdetail WHERE id=ld_expensebudget.expensebudgetid) WHERE FIND_IN_SET(expensebudgetid,tmp_mybillid);

END ;;
DELIMITER ;
